source = '''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    divider_rows = [r for r, row in enumerate(grid)
                    if len(set(row)) == 1 and row[0] != background]
    divider_cols = [c for c in range(w)
                    if len({grid[r][c] for r in range(h)}) == 1
                    and grid[0][c] != background]

    def spans(size, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_spans = spans(h, divider_rows)
    col_spans = spans(w, divider_cols)
    blocks = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if any(grid[r][c] != background
                   for r in range(r0, r1) for c in range(c0, c1)):
                blocks.append((r0, r1, c0, c1))
    if not blocks:
        return [row[:] for row in grid]
    sr0, sr1, sc0, sc1 = blocks[0]
    out = [row[:] for row in grid]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if (r0, r1, c0, c1) == (sr0, sr1, sc0, sc1):
                continue
            for dr in range(min(sr1 - sr0, r1 - r0)):
                for dc in range(min(sc1 - sc0, c1 - c0)):
                    out[r0 + dr][c0 + dc] = grid[sr0 + dr][sc0 + dc]
    return out
'''
